/**
 * Bundled per-module stats for the ships UI's 装备选择 module-chain tooltip
 * cards (耐久 / 射程 / 装填), generated by
 * `scripts/extract/build_module_stats.py` — one pack per realm, keyed by the
 * chain bundle's module entry NAME (the same join key the packs' generator
 * documents):
 *
 *   - `ship_module_stats.json`        WG snapshot (`wg-<build>`)
 *   - `ship_module_stats_lesta.json`  Lesta snapshot (`lesta-<build>`)
 *
 * A module entry carries only what the current client's ship subtrees really
 * hold: a hull's `health`, an artillery mount's `maxDist` firing range and
 * first-hardpoint `shotDelay` reload, a torpedo-tube config's hardpoint
 * reload (its shells carry no decodable range — documented in the extractor).
 * Fire control / engine / CV-armament rows are listed with null stats so the
 * UI can tell "known empty" from "unextracted": both render the panel's "—",
 * but only the latter would justify a TODO note. Never fabricate.
 */
import lestaRaw from "@/data/ship_module_stats_lesta.json";
import wgRaw from "@/data/ship_module_stats.json";
import type { TechTreeRealm } from "./techTreeData";

/** What the tooltip card shows for one module. */
export interface ModuleStats {
  /** Numeric GameParams id of the mounted entity, when the dump carries one. */
  gpid: number | null;
  /** Raw ucType of the slot the module was extracted from ("_Hull"). */
  ucType: string;
  /** Card-model tag: hull / artillery / torpedoes / suo / engine / other. */
  kind: "hull" | "artillery" | "torpedoes" | "suo" | "engine" | "other";
  /** Hull hit points. */
  health: number | null;
  /** Firing range in meters (artillery mounts). */
  rangeM: number | null;
  /** Reload in seconds (artillery mounts / torpedo tubes, first hardpoint). */
  reloadS: number | null;
}

interface ModuleStatsPack {
  source: string;
  modules: Record<string, ModuleStats>;
}

const PACKS: Record<TechTreeRealm, ModuleStatsPack> = {
  wg: wgRaw as ModuleStatsPack,
  lesta: lestaRaw as ModuleStatsPack,
};

/** True when the realm's pack was generated at all (the bundle always ships
 *  both; defensive for a realm regenerating without its pack). */
export function hasModuleStats(realm: TechTreeRealm): boolean {
  return Object.keys(PACKS[realm]?.modules ?? {}).length > 0;
}

/** Stats of one module by its chain-bundle entry name; null when the realm's
 *  pack does not know the module (the card renders its "—" placeholders). */
export function moduleStatsOf(
  realm: TechTreeRealm,
  moduleName: string | null | undefined,
): ModuleStats | null {
  if (!moduleName) return null;
  return PACKS[realm]?.modules[moduleName] ?? null;
}
